IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.ComunicacionDestinatario') AND name=N'IX_ComDest_Empleado_Estado') CREATE INDEX IX_ComDest_Empleado_Estado ON dbo.ComunicacionDestinatario(IdEmpleadoCj,Estado,Leido,Confirmado) INCLUDE(IdComunicacion,FechaLectura,FechaConfirmacion);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.Comunicacion') AND name=N'IX_Comunicacion_Activa_Fecha') CREATE INDEX IX_Comunicacion_Activa_Fecha ON dbo.Comunicacion(Activo,Estado,FechaCreacion DESC) INCLUDE(Tipo,Prioridad,TipoPersistencia,Titulo);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.DispositivoMovil') AND name=N'UX_Dispositivo_Empleado_Device_Activo') CREATE UNIQUE INDEX UX_Dispositivo_Empleado_Device_Activo ON dbo.DispositivoMovil(IdEmpleadoCj,DeviceId) WHERE Activo=1;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.DispositivoMovil') AND name=N'IX_Dispositivo_PushToken_Activo') CREATE INDEX IX_Dispositivo_PushToken_Activo ON dbo.DispositivoMovil(PushToken) WHERE Activo=1;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.ComunicacionEvento') AND name=N'IX_ComEvento_Comunicacion_Empleado') CREATE INDEX IX_ComEvento_Comunicacion_Empleado ON dbo.ComunicacionEvento(IdComunicacion,IdEmpleadoCj,FechaEvento DESC);
